// Why Code: decides whether this case must wait, by comparing its place in the processing order with every other case for the same account, using their statuses as they are now. That needs all of the account's cases at once.
const s = $('Load settings').first().json.settings;
const me = $('This case').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.id !== undefined);
const max = Number(s.maxAttempts);
const stuckBefore = $now.minus({ minutes: Number(s.stuckMinutes) }).toMillis();

// Processing order: relevant date, then move-outs before move-ins, then batch, then row (then id, to break ties).
const orderKey = (r) => [String(r.relevantDate ?? ''), r.changeReason === 'TENANCY_START' ? 1 : 0, String(r.batchId ?? ''), Number(r.rowNumber) || 0, Number(r.id) || 0];
const comesBefore = (a, b) => {
  const ka = orderKey(a);
  const kb = orderKey(b);
  for (let i = 0; i < ka.length; i++) {
    if (ka[i] < kb[i]) return true;
    if (ka[i] > kb[i]) return false;
  }
  return false;
};
const unfinished = (r) => r.status === 'new' || r.status === 'in_progress' || (r.status === 'failed' && Number(r.attempts) < max);
const stuck = (r) => !r.lastAttemptAt || new Date(r.lastAttemptAt).getTime() < stuckBefore;

const current = rows.find((r) => r.id === me.id);
if (!current) {
  return [{ json: { runNow: false, why: 'case no longer found', caseId: me.id } }];
}
const ready =
  current.status === 'new' ||
  (current.status === 'failed' && Number(current.attempts) < max) ||
  (current.status === 'in_progress' && Number(current.attempts) < max && stuck(current));
const blocker = rows.find((r) => r.id !== current.id && unfinished(r) && comesBefore(r, current));

return [{
  json: {
    runNow: ready && !blocker,
    why: !ready ? `no longer ready (${current.status}, ${current.attempts} tries)` : blocker ? `held: case ${blocker.id} for the same account is unfinished (${blocker.status})` : 'ready',
    caseId: current.id,
    expectedStatus: current.status,
    expectedAttempts: Number(current.attempts) || 0,
  },
}];
